#include <stdio.h>
int main() {
    int choice, quantity, unit = 0;
    scanf("%d %d", &choice, &quantity);
    if (quantity <= 0) {
        printf("Invalid Quantity\n");
        return 0;
    }
    switch (choice) {
        case 1: unit = 80;  break;
        case 2: unit = 150; break;
        case 3: unit = 180; break;
        case 4: unit = 120; break;
        default: printf("Invalid Choice\n"); return 0;
    }
    printf("Total Bill: %d\n", unit * quantity);
    return 0;
}

#include <stdio.h>
int calculateTotal(int m1, int m2, int m3) {
    return m1 + m2 + m3;
}
void applyGrace(int *total, int grace) {
    *total = *total + grace;
    if (*total > 300) {
        *total = 300;
    }
}
int main() {
    int m1, m2, m3, grace, total;
    scanf("%d %d %d %d", &m1, &m2, &m3, &grace);
    if (m1 < 0 || m1 > 100 || m2 < 0 || m2 > 100 || m3 < 0 || m3 > 100 || grace < 0 || grace > 5) {
        printf("Invalid Input\n");
        return 0;
    }
    total = calculateTotal(m1, m2, m3);
    applyGrace(&total, grace);
    printf("Total: %d\n", total);
    printf("Average: %.2f\n", total / 3.0);
    if (total / 3.0 >= 40)
        printf("Pass\n");
    else
        printf("Fail\n");
    return 0;
}

#include <stdio.h>
int evenSum(int n) {
    if (n == 0)
        return 0;
    return 2 * n + evenSum(n - 1);
}
int main() {
    int n;
    scanf("%d", &n);
    if (n < 0 || n > 20) {
        printf("Invalid Input\n");
        return 0;
    }
    printf("Score: %d\n", evenSum(n));
    return 0;
}

#include <stdio.h>
int ways(int n) {
    if (n == 0 || n == 1)
        return 1;
    return ways(n - 1) + ways(n - 2);
}
int main() {
    int n;
    scanf("%d", &n);
    if (n < 0) {
        printf("Invalid Input\n");
        return 0;
    }
    printf("%d\n", ways(n));
    return 0;
}
